INSERT INTO public.seguimiento (id, mtt_id, activador, fecha_visita, observacion, verificado_gerencia, fecha_verificacion) VALUES (2265, 2265, 'N/D', NULL, 'ZONA EN SILENCIO, SE INSTALÓ UN NODO NGN (2012), ASICOMO TAMBIEN TODAS LAS REDES, EL PROYECTO ABARCABA 6 SECTORES (LOS GÓMEZ,SABANA MAR,ARAPANO,LOS PUESTOS,LAGUNA DE RAYA,MATA REDONDA), SIN EMBARGO, NO SE INSTALO NINGUNA LÍNEA TELEFÓNICA, EN VARIAS OPORTUNIDADES ,HUBO HURTOS DE CABLES, LOS VOCEROS DE LA MTT DENUNCIARON, PERO CONTINUARON LOS HURTOS, EN EL 2024 EL NODO FUE TRASLADADO AL SECTOR DE ANTOLÍN DEL CAMPO,PARA EL PROYECTO DE LA CURVA DEL GALLO Y SE DECLARÓ TODOS LOS SECTORES, ZONA EN SILENCIO. SE ACTUALIZA EL 27/08/26 , LA VOCERIA DE MTT CON EL APOYO DE LA ENCARGADA DE LA SALA DE AUTOGOBIERNO | Bitácora: 27/08/2026: RENOVACION DE VOCERIAS EN EL AMBITO DE LA COMUNA: LOS PUEBLOS DE MARIA GUEVARA. 11/08/2009: CONFORMACION DE MTT', true, NULL);
