INSERT INTO public.seguimiento (id, mtt_id, activador, fecha_visita, observacion, verificado_gerencia, fecha_verificacion) VALUES (2555, 2555, 'N/D', '2026-09-24', 'DEBIDO A UN CABLE CENTRAL DAÑADO, LA COMUNIDAD ESTA SIN SERVICIO Y COMO CONSECUENCIA, LOS VOCEROS NO SE QUIEREN REUNIR, EL CC DEL SECTOR NO ESTA RENOVADO. COMO ESTRATEGIA SE IMPULSA LA CONFORMACION DE LOS COMITES DE MTT , A TRAVES DE LAS SALAS DE AUTOGOBIERNO DEL MUNICIPIO. 17/09/26 SE LOGRO ESTABLECER COMUNICACION CON EL ENCARGADO DE LA SALA DE AUTOGOBIERNO Y CON ELLO SE CONFORMO UNA NUEVA MTT COMUNAL (UNIDOS COMO ARTESANOS),POR TAL MOTIVO SE PROCEDERA A CERRAR LA MTT MARBELIS SALGADO, YA QUE, LA MISMA SOLO ABARCA EL SECTOR DEL MACO. 24/09/26 se realiza levantamiento de Acta de cierre dando formalidad a la misma ,avalado con el encargado de la Sala de Autogobierno, Sr Simon Marin y los CC del sector. | Bitácora: NO RENOVADA', true, NULL);
