SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;

DROP TABLE IF EXISTS public.mtt_secuencias_parroquia CASCADE;
DROP TABLE IF EXISTS public.seguimiento CASCADE;
DROP TABLE IF EXISTS public.vocerias CASCADE;
DROP TABLE IF EXISTS public.organizacion_comunal CASCADE;
DROP TABLE IF EXISTS public.mtt_principal CASCADE;
DROP TABLE IF EXISTS public.usuarios CASCADE;
DROP TABLE IF EXISTS public.roles CASCADE;
DROP TABLE IF EXISTS public.parroquias CASCADE;
DROP TABLE IF EXISTS public.municipios CASCADE;
DROP TABLE IF EXISTS public.estados CASCADE;
DROP TABLE IF EXISTS public.regiones CASCADE;

CREATE TABLE public.regiones (
    id SERIAL PRIMARY KEY,
    nombre character varying(50) NOT NULL UNIQUE
);

CREATE TABLE public.estados (
    id SERIAL PRIMARY KEY,
    nombre character varying(100) NOT NULL UNIQUE,
    cod_entidad character varying(2) NOT NULL UNIQUE,
    region_id integer REFERENCES public.regiones(id)
);

CREATE TABLE public.municipios (
    id SERIAL PRIMARY KEY,
    nombre character varying(100) NOT NULL,
    cod_municipio character varying(2) NOT NULL,
    estado_id integer NOT NULL REFERENCES public.estados(id)
);

CREATE TABLE public.parroquias (
    id SERIAL PRIMARY KEY,
    nombre character varying(100) NOT NULL,
    cod_parroquia character varying(2) NOT NULL,
    codigo_ubigeo character varying(6) NOT NULL UNIQUE,
    municipio_id integer NOT NULL REFERENCES public.municipios(id)
);

CREATE TABLE public.roles (
    id SERIAL PRIMARY KEY,
    nombre character varying(100) NOT NULL UNIQUE,
    nivel_acceso character varying(50),
    descripcion text
);

CREATE TABLE public.usuarios (
    id SERIAL PRIMARY KEY,
    usuario character varying(50) NOT NULL UNIQUE,
    password_hash character varying(255) NOT NULL,
    rol_id integer REFERENCES public.roles(id),
    nombre character varying(150),
    cedula character varying(20),
    activo boolean DEFAULT true
);

CREATE TABLE public.mtt_principal (
    id SERIAL PRIMARY KEY,
    codigo_mtt character varying(50) UNIQUE,
    parroquia_id integer REFERENCES public.parroquias(id),
    nombre text DEFAULT 'N/D',
    tipo character varying(50),
    fecha_creacion date,
    estatus character varying(50) DEFAULT 'Pendiente GDC',
    fecha_cambio_estatus date,
    tiene_georreferenciacion boolean DEFAULT false,
    latitud numeric(12,8),
    longitud numeric(12,8),
    correo_electronico character varying(150),
    red_x character varying(100),
    red_instagram character varying(100),
    red_facebook character varying(100),
    red_tiktok character varying(100),
    eje_territorial character varying(100),
    zona_cantv boolean DEFAULT false,
    medio_transmision character varying(50),
    otras_operadoras character varying(50),
    elemento_red character varying(100),
    huella_gpon boolean DEFAULT false,
    central_cantv_cercana character varying(150),
    nombre_nodo character varying(150)
);

CREATE TABLE public.organizacion_comunal (
    id SERIAL PRIMARY KEY,
    mtt_id integer REFERENCES public.mtt_principal(id) ON DELETE CASCADE,
    sector text DEFAULT 'N/D',
    cec_comuna character varying(50),
    comuna_nombre text DEFAULT 'N/D',
    comuna_codigo character varying(50),
    consejo_nombre text DEFAULT 'N/D',
    consejo_situr character varying(50),
    sac_vinculada boolean DEFAULT false,
    sac_conectada character varying(50),
    sala_gobierno_vinculada boolean DEFAULT false,
    num_comunas integer,
    num_cc integer,
    num_comites integer,
    comite_tecnologia boolean DEFAULT false,
    comite_medios boolean DEFAULT false,
    num_familias integer,
    num_habitantes integer
);

CREATE TABLE public.vocerias (
    id SERIAL PRIMARY KEY,
    mtt_id integer REFERENCES public.mtt_principal(id) ON DELETE CASCADE,
    estatus_voceria character varying(50),
    total_mujeres integer DEFAULT 0,
    total_hombres integer DEFAULT 0,
    otras_mujeres integer DEFAULT 0,
    otros_hombres integer DEFAULT 0,
    total_voceros integer GENERATED ALWAYS AS (total_mujeres + total_hombres) STORED,
    v1_nombre text DEFAULT 'N/D',
    v1_cedula character varying(20),
    v1_nacimiento date,
    v1_sexo character varying(15),
    v1_telefono character varying(20) DEFAULT 'N/D',
    v2_nombre text DEFAULT 'N/D',
    v2_cedula character varying(20),
    v2_nacimiento date,
    v2_sexo character varying(15),
    v2_telefono character varying(20) DEFAULT 'N/D'
);

CREATE TABLE public.seguimiento (
    id SERIAL PRIMARY KEY,
    mtt_id integer REFERENCES public.mtt_principal(id) ON DELETE CASCADE,
    activador character varying(150) DEFAULT 'N/D',
    fecha_visita date,
    observacion text DEFAULT 'SIN OBSERVACIÓN',
    verificado_gerencia boolean DEFAULT false,
    fecha_verificacion date
);

CREATE TABLE public.mtt_secuencias_parroquia (
    id SERIAL PRIMARY KEY,
    codigo_ubigeo_6d character varying(6) NOT NULL UNIQUE,
    parroquia_id integer REFERENCES public.parroquias(id),
    ultimo_correlativo integer NOT NULL DEFAULT 0,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);

